// Port of app/domain/answering/pseudonymize.py (SPEC-001 R4, CHG-001 D2).
const EMAIL = /[\p{L}\p{N}_.+-]+@[\p{L}\p{N}_-]+(?:\.[\p{L}\p{N}_-]+)+/gu;
const NIE = /(?<![\p{L}\p{N}_])[XYZxyz][\s-]?\p{Nd}{7}[\s-]?[A-Za-z](?![\p{L}\p{N}_])/gu;
const DNI = /(?<![\p{L}\p{N}_])\p{Nd}{8}[\s-]?[A-Za-z](?![\p{L}\p{N}_])/gu;
const PHONE = /(?<![\p{L}\p{N}_+])(?:(?:\+|00)34[\s.-]?)?[6789]\p{Nd}{2}(?:[\s.-]?\p{Nd}){6}(?![\p{L}\p{N}_])/gu;
const NAME_INTRO = /(?<![\p{L}\p{N}_])(?:me\s+llamo|mi\s+nombre\s+es|a\s+nombre\s+de)\s+/giu;
const WORD = /[A-Za-zÁÉÍÓÚÜÑáéíóúüñ]+/y;
const SPACES = /\s+/y;
const NAME_CONNECTORS = new Set(['de', 'del', 'la', 'las', 'los']);
const MAX_NAME_WORDS = 4;
const NOT_A_SURNAME = new Set([
  'y', 'e', 'o', 'u', 'que', 'quiero', 'quisiera', 'querría', 'para', 'por', 'con', 'sin',
  'de', 'del', 'la', 'el', 'los', 'las', 'un', 'una', 'tengo', 'necesito', 'me', 'mi',
  'a', 'al', 'en', 'es', 'soy', 'pero', 'porque', 'gracias', 'hola', 'buenas', 'buenos',
  'cuánto', 'cuanto', 'cómo', 'como', 'qué', 'cuándo', 'cuando', 'pido', 'pedir',
]);

function matchAt(re, text, pos) {
  re.lastIndex = pos;
  const m = re.exec(text);
  return m ? { text: m[0], end: pos + m[0].length } : null;
}
const isUpperChar = (c) => c !== c.toLowerCase();
const isLowerWord = (w) => w === w.toLowerCase() && w !== w.toUpperCase();

function capitalizedNameEnd(text, first) {
  let end = first.end;
  let words = 1;
  let cursor = first.end;
  while (words < MAX_NAME_WORDS) {
    let connectorsEnd = cursor;
    let word = null;
    while (true) {
      const gap = matchAt(SPACES, text, connectorsEnd);
      word = gap ? matchAt(WORD, text, gap.end) : null;
      if (word && NAME_CONNECTORS.has(word.text.toLowerCase())) {
        connectorsEnd = word.end;
        continue;
      }
      break;
    }
    if (!word || !isUpperChar(word.text[0])) break;
    end = cursor = word.end;
    words += 1;
  }
  return end;
}

function lowercaseNameEnd(text, first) {
  if (NOT_A_SURNAME.has(first.text.toLowerCase())) return null;
  const gap = matchAt(SPACES, text, first.end);
  const second = gap ? matchAt(WORD, text, gap.end) : null;
  if (second && isLowerWord(second.text) && !NOT_A_SURNAME.has(second.text)) return second.end;
  return first.end;
}

function nameEnd(text, start) {
  const first = matchAt(WORD, text, start);
  if (!first) return null;
  return isUpperChar(first.text[0]) ? capitalizedNameEnd(text, first) : lowercaseNameEnd(text, first);
}

function replaceNames(text) {
  let out = '';
  let pos = 0;
  NAME_INTRO.lastIndex = 0;
  let intro;
  while ((intro = NAME_INTRO.exec(text)) !== null) {
    const introEnd = intro.index + intro[0].length;
    if (intro.index < pos) continue;
    const end = nameEnd(text, introEnd);
    if (end === null) continue;
    out += text.slice(pos, introEnd) + '[NOMBRE]';
    pos = end;
  }
  return out + text.slice(pos);
}

function pseudonymize(text) {
  let t = text.replace(EMAIL, '[EMAIL]');
  t = t.replace(NIE, '[DNI]');
  t = t.replace(DNI, '[DNI]');
  t = t.replace(PHONE, '[TELEFONO]');
  return replaceNames(t);
}

const msg = $json.message ?? {};
return { json: { chatId: msg.chat?.id, question: pseudonymize(msg.text ?? '') } };

// SPEC-010 reception module (specs/011-reception-handoff/spec.md, plan.md Step 1).
// Paste-ready: the n8n Code nodes «Recepción», «Mensaje del grupo», «Componer recepción», «Grupo de
// recepción», «Respuesta de recepción» and «Componer respuesta» of lifecenter-telegram-demo carry this exact
// code followed only by their wiring. No require, no network, no state: the handoff rows live
// in Neon (007_reception.sql), and no message text is ever stored.

// --- Fixed texts (spec "Fixed texts", verified by the human 2026-11-24) ---
const TEXTS = {
  HANDOFF_CONFIRM: '¿Quieres que pase tu consulta a recepción? Te pediré que la escribas en un mensaje; la leerán sin tu nombre ni tu teléfono.',
  HANDOFF_WRITE: 'Escribe en un mensaje lo que quieres que lea recepción. No incluyas datos personales.',
  HANDOFF_SENT: 'Hecho. He pasado tu consulta a recepción (código {codigo}). Te responderán por aquí en horario de la clínica.',
  HANDOFF_CANCELLED: 'De acuerdo, no paso nada a recepción.',
  HANDOFF_FAILED: 'Ahora mismo no puedo pasar tu consulta. Llama a recepción en horario de atención.',
  GROUP_HEADER: '[{codigo}] Motivo: {motivo}',
  GROUP_FOOTER: 'Responde a este mensaje para contestar al paciente.',
  RECEPTION_REPLY: 'Recepción de LifeCenter ({codigo}): {texto}',
  HANDOFF_CLOSED: 'Esta consulta ya está cerrada.',
  COMPLAINT_CONFIRM: 'Siento lo ocurrido. ¿Quieres que pase tu queja a recepción? Te pediré que la escribas en un mensaje; la leerán sin tu nombre ni tu teléfono.',
  RATING_THANKS: 'Gracias por tu valoración.',
};
const LABELS = { si: 'Sí, pasar a recepción', no: 'No', cerrar: 'Cerrar', cerrada: 'Cerrada', up: '👍', down: '👎' };
// The existing labels and callbacks this module reuses (CHG-001 D8, SPEC-007).
const HANDOFF_LABEL = 'Hablar con recepción';
const BOOKING_LABEL = 'Pedir cita';
const BOOKING_MENU = 'bk:menu';

// --- Reasons (RH2, RH13): the code in the callback, and what reception reads ---
const REASONS = { a: 'abstención', u: 'urgencia', p: 'petición', q: 'queja' };

// --- Codes (P3): R- (handoff) or Q- (complaint) + 4 characters with no look-alikes (no 0, O, 1, I, L).
// The database generates them (unique among open handoffs); this only recognizes them.
const CODE_ALPHABET = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
const CODE_PATTERN = /^[RQ]-[ABCDEFGHJKMNPQRSTUVWXYZ2-9]{4}$/;

// --- The reason of «Hablar con recepción» under a reply of B (RH2). B does not change. ---
const ABSTENTION_REASONS = ['below_threshold', 'model_abstained', 'validation_failed'];
function handoffReasonFor(result) {
  const reason = result && result.reason;
  if (reason === 'urgency') return 'u';
  if (ABSTENTION_REASONS.includes(reason)) return 'a';
  return 'p';
}

const fill = (t, vars) => Object.entries(vars).reduce((s, [k, v]) => s.replace(`{${k}}`, v), t);

// --- The confirmation (RH1, RH13): «Sí, pasar a recepción» keeps the reason; «No» needs nothing ---
function confirmView(reason) {
  return {
    text: reason === 'q' ? TEXTS.COMPLAINT_CONFIRM : TEXTS.HANDOFF_CONFIRM,
    rows: [[{ text: LABELS.si, data: `hs:${reason}` }], [{ text: LABELS.no, data: 'hn' }]],
  };
}

// --- The message posted in the reception group (RH4, RH5, P4): code, reason, the pseudonymized text,
// and «Cerrar». No name, phone, Telegram user or appointment. An urgency is always marked as one. ---
function groupMessage({ code, reason, text, urgent }) {
  const motivo = REASONS[urgent ? 'u' : reason] || REASONS.p;
  return {
    text: `${fill(TEXTS.GROUP_HEADER, { codigo: code, motivo })}\n\n${text}\n\n${TEXTS.GROUP_FOOTER}`,
    rows: [[{ text: LABELS.cerrar, data: `hc:${code}` }]],
  };
}

// --- What the patient reads (RH4, RH9) ---
const sentText = (code) => fill(TEXTS.HANDOFF_SENT, { codigo: code });
const receptionReply = (code, text) => fill(TEXTS.RECEPTION_REPLY, { codigo: code, texto: text });

// --- An update from a group (RH9–RH12): only a text reply to a bot message, or «Cerrar», in the
// registered reception group. Everything else, from any group, is ignored with no reply. ---
function groupAction(route, receptionChatId) {
  const ignore = { action: 'ignore' };
  if (!route || route.kind !== 'group' || !receptionChatId || String(route.chatId) !== String(receptionChatId)) return ignore;
  if (route.callbackData) {
    const m = /^hc:(.+)$/.exec(route.callbackData);
    return m && CODE_PATTERN.test(m[1])
      ? { action: 'close', code: m[1], callbackQueryId: route.callbackQueryId, messageId: route.messageId } : ignore;
  }
  if (route.replyToMessageId && route.replyToBot && typeof route.text === 'string' && route.text.trim()) {
    return { action: 'forward', replyToMessageId: route.replyToMessageId, text: route.text };
  }
  return ignore;
}

// --- The keyboard under B's replies (RH2, RH16): «Hablar con recepción» with its reason, «Pedir cita»
// (SPEC-007), and 👍/👎 only under an answered reply. One button per row, because A's «Responder reserva
// (n)» nodes have one button per row (human, 2026-11-24). ---
function answerRows(result) {
  const rows = [];
  if (result && result.handoff) rows.push([{ text: HANDOFF_LABEL, data: `handoff:${handoffReasonFor(result)}` }]);
  if (result && result.offer_booking === true) rows.push([{ text: BOOKING_LABEL, data: BOOKING_MENU }]);
  if (result && result.reason === 'answered') rows.push([{ text: LABELS.up, data: 'rt:u' }], [{ text: LABELS.down, data: 'rt:d' }]);
  return rows;
}

// --- The Telegram node's inlineKeyboard parameter, built from the rows (the same shape as citas.js) ---
function toTelegramKeyboard(rows) {
  return {
    rows: rows.map((r) => ({ row: { buttons: r.map((b) => ({ text: b.text, additionalFields: { callback_data: b.data } })) } })),
  };
}

// --- n8n wiring ("Componer respuesta", SPEC-005 P6, SPEC-006, SPEC-007 BK5, SPEC-010 RH2, RH16) ---
// B returns no identifier; A attaches its own chat id. The buttons: «Hablar con recepción» with its reason,
// «Pedir cita», and 👍/👎 under an answered reply, sent by «¿Cuántos botones?».
const rows = answerRows($json);
return { json: { ...$json, chatId: $('Seudonimizar').item.json.chatId,
  keyboard: rows.length ? 'booking' : 'none', inlineKeyboard: toTelegramKeyboard(rows) } };

// SPEC-006 consent module (specs/006-consent/spec.md, plan.md Step 1).
// Paste-ready: the n8n Code nodes "Clasificar" and "Decidir" of lifecenter-telegram-demo carry this
// exact code followed only by their input/output wiring (C23). No require, no network, no state.

// --- Configuration (C22). Change the version whenever CONSENT_NOTICE changes: everyone is asked again.
const CONSENT_TEXT_VERSION = '1';

// --- Fixed texts (spec "Fixed texts", approved by the human 2026-11-21) ---
const CONSENT_NOTICE =
  'Hola, soy el asistente de LifeCenter. Para responderte: quito tu nombre, teléfono, DNI y email ' +
  'de los mensajes antes de procesarlos; envío la consulta a un modelo de IA externo (Gemini, de ' +
  'Google), y guardo el recorrido de cada consulta, sin tus datos, durante 30 días. Si me cuentas un ' +
  'síntoma te daré siempre el teléfono de la clínica. Esto es una demostración: no escribas datos ' +
  'reales. ¿Aceptas?';
const ACCEPTED_TEXT = 'Gracias. Ya puedes escribirme tu consulta.';
const REJECTED_TEXT =
  'De acuerdo, no procesaré tus consultas. Puedes llamar a recepción. Si cambias de opinión, escribe /privacidad.';
const REVOKED_TEXT =
  'He retirado tu consentimiento. No procesaré más consultas tuyas. Si cambias de opinión, escribe /privacidad.';
const STATUS_ACCEPTED = 'Estado: aceptaste este aviso el {fecha}.';
const STATUS_NONE = 'Estado: no has aceptado este aviso.';
// Copies of CHG-001 texts this module now composes: D7 (error) and D12 (no text).
const ERROR_TEXT = 'Ahora mismo no puedo responder. ¿Quieres que pase tu consulta a recepción?';
const TEXT_ONLY_TEXT = 'Solo puedo leer mensajes de texto. ¿Me escribes tu consulta?';
// SPEC-010 (spec "Fixed texts", verified 2026-11-24): the D8 text, now chosen here, for a handoff without
// consent; and the reply to a complaint without consent.
const HANDOFF_NO_CONSENT_TEXT = 'Ahora mismo no puedo pasar tu consulta automáticamente. Llama a recepción en horario de atención.';
const COMPLAINT_NO_CONSENT_TEXT =
  'Para pasar tu queja a recepción necesito tu consentimiento (/privacidad). También puedes llamar a recepción en horario de atención.';

// --- Buttons (C7): labels and callback_data, each at most 64 bytes ---
const BUTTON_LABELS = {
  handoff: 'Hablar con recepción',
  accept: 'Acepto',
  reject: 'No acepto',
  withdraw: 'Retirar consentimiento',
};
const CALLBACK_HANDOFF = 'handoff';
const CALLBACK_WITHDRAW = 'consent:withdraw';
const callbackAccept = (version = CONSENT_TEXT_VERSION) => `consent:accept:${version}`;
const callbackReject = (version = CONSENT_TEXT_VERSION) => `consent:reject:${version}`;

// --- Commands (spec "Command"): exactly /start or /privacidad, optionally @<bot>, spaces ignored,
// in any letter case (phone keyboards capitalize the first letter) ---
// SPEC-007: /cita and /micita are booking commands (any letter case, like the others).
// SPEC-010: /queja opens the complaint path (RH13).
const COMMAND = /^\s*\/(start|privacidad|cita|micita|queja)(?:@[A-Za-z0-9_]+)?\s*$/i;
const BOOKING_COMMANDS = ['cita', 'micita'];
function parseCommand(text) {
  const m = COMMAND.exec(typeof text === 'string' ? text : '');
  return m ? m[1].toLowerCase() : null;
}

// --- Buttons: callback_data → { kind, version } ---
const CONSENT_CALLBACK = /^consent:(accept|reject):(.+)$/;
// SPEC-010 RH2, RH3, RH6, RH17: handoff:<reason> (the old `handoff` is a request), «Sí, pasar a
// recepción» (hs:<reason>), «No» (hn), and the ratings (rt:u / rt:d). «Cerrar» (hc:) only exists in groups.
const HANDOFF_CALLBACK = /^(handoff|hs):([aupq])$/;
const RATING_CALLBACK = /^rt:([ud])$/;
function parseCallback(data) {
  if (data === CALLBACK_HANDOFF) return { kind: 'handoff', version: null, reason: 'p' };
  const h = HANDOFF_CALLBACK.exec(typeof data === 'string' ? data : '');
  if (h) return { kind: h[1] === 'hs' ? 'handoff_confirm' : 'handoff', version: null, reason: h[2] };
  if (data === 'hn') return { kind: 'handoff_cancel', version: null };
  const rt = RATING_CALLBACK.exec(typeof data === 'string' ? data : '');
  if (rt) return { kind: 'rating', version: null, value: rt[1] === 'u' ? 'up' : 'down' };
  if (data === CALLBACK_WITHDRAW) return { kind: 'withdraw', version: null };
  if (typeof data === 'string' && data.startsWith('bk:')) return { kind: 'booking_button', version: null }; // SPEC-007
  const m = CONSENT_CALLBACK.exec(typeof data === 'string' ? data : '');
  return m ? { kind: m[1], version: m[2] } : { kind: 'unknown_button', version: null };
}

// --- A Telegram update → route. fromId is a string: it is only ever passed to Neon as $1 (C18). ---
function classifyUpdate(update) {
  const asId = (v) => (v === undefined || v === null ? null : String(v));
  const cq = update && update.callback_query;
  // SPEC-010 RH12, A3: anything from a chat that is not private is a group update. It never carries the
  // sender's id, and never reaches the consent logic.
  const chatOf = cq ? cq.message && cq.message.chat : update && update.message && update.message.chat;
  if (chatOf && chatOf.type && chatOf.type !== 'private') {
    const gm = cq ? cq.message : update.message;
    const reply = !cq && gm.reply_to_message;
    return {
      kind: 'group',
      chatId: asId(chatOf.id),
      messageId: gm && gm.message_id !== undefined ? gm.message_id : null,
      replyToMessageId: reply ? reply.message_id : null,
      replyToBot: !!(reply && reply.from && reply.from.is_bot),
      text: !cq && typeof gm.text === 'string' ? gm.text : null,
      callbackData: cq ? cq.data : null,
      callbackQueryId: cq && cq.id !== undefined ? cq.id : null,
    };
  }
  if (cq) {
    const parsed = parseCallback(cq.data);
    const route = {
      kind: parsed.kind,
      fromId: asId(cq.from && cq.from.id),
      chatId: cq.message && cq.message.chat ? cq.message.chat.id : null,
      callbackQueryId: cq.id === undefined ? null : cq.id,
      version: parsed.version,
    };
    if (parsed.kind === 'booking_button') return { ...route, data: cq.data }; // SPEC-007
    if ('reason' in parsed) return { ...route, reason: parsed.reason }; // SPEC-010
    if ('value' in parsed) return { ...route, value: parsed.value };
    return route;
  }
  const m = (update && update.message) || {};
  const hasText = typeof m.text === 'string' && m.text !== '';
  const command = hasText ? parseCommand(m.text) : null;
  const booking = BOOKING_COMMANDS.includes(command);
  const complaint = command === 'queja'; // SPEC-010 RH13
  const route = {
    kind: booking ? 'booking_command' : complaint ? 'complaint_command' : command || (hasText ? 'text' : 'other'),
    fromId: asId(m.from && m.from.id),
    chatId: m.chat ? m.chat.id : null,
    callbackQueryId: null,
    version: null,
  };
  return booking || complaint ? { ...route, data: command } : route; // SPEC-007: /cita, /micita; SPEC-010: /queja
}

// --- SPEC-010 RH13, RH14: complaint phrases, a strict list (evals/complaint_phrases.yaml) ---
// Works on the pseudonymized text. A match only opens the /queja confirmation; it never posts anything.
function normalizeComplaintText(text) {
  return String(text ?? '')
    .toLowerCase()
    .normalize('NFD').replace(/\p{M}+/gu, '')
    .replace(/\[(nombre|telefono|dni|email)\]/g, ' ')
    .replace(/[^\p{L}\p{N}\s]+/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
const COMPLAINT_WORDS = /\b(?:queja|quejas|quejar|quejarme|reclamacion|reclamaciones|reclamar)\b/;
// Not a complaint: no complaint, someone else complaining, or an insurance claim.
const COMPLAINT_BLOCKERS = [
  /\b(?:no tengo|sin) (?:ninguna )?quejas?\b/,
  /\bno me quejo\b/,
  /\bse (?:queja|quejan|quejaba|quejo)\b/,
  /\b(?:seguro|aseguradora|reembolso|mutua|tramit\w*)\b/,
];
function detectComplaintPhrase(text) {
  const t = normalizeComplaintText(text);
  return COMPLAINT_WORDS.test(t) && !COMPLAINT_BLOCKERS.some((re) => re.test(t));
}

// --- SPEC-008 MC10: the only booking buttons allowed without consent (one start code each) ---
const CANCEL_WITHOUT_CONSENT = /^bk:(?:a|ac|v):[0-9a-z]{1,8}$/;

// --- Consent in force (C22): accepted with the current version; anything else is no consent ---
function isConsentInForce(row) {
  return !!row && row.status === 'accepted' && row.text_version === CONSENT_TEXT_VERSION;
}

// --- dd/mm/aaaa in Europe/Madrid ---
function formatDate(decidedAt) {
  const parts = new Intl.DateTimeFormat('es-ES', {
    timeZone: 'Europe/Madrid', day: '2-digit', month: '2-digit', year: 'numeric',
  }).formatToParts(new Date(decidedAt));
  const get = (type) => parts.find((p) => p.type === type).value;
  return `${get('day')}/${get('month')}/${get('year')}`;
}

// --- What to do with an update (plan Step 1, decision table; C2–C16) ---
// urgency: the output of "Detectar urgencia" (B's wiring), or null if it did not run.
// consent: the row from consent_get ({} when there is none); lookupFailed: the lookup errored.
// SPEC-010: question is the pseudonymized text (for the complaint phrases); handoffAwaiting says whether a
// handoff of this patient waits for the text for reception (from the consent lookup).
function decide({ route, urgency, consent, lookupFailed, question = null, handoffAwaiting = false }) {
  const reply = (text, keyboard) => ({ action: 'reply', text, keyboard });
  const notice = reply(CONSENT_NOTICE, 'consent');
  const inForce = !lookupFailed && isConsentInForce(consent);
  const kind = route && route.kind;

  const urgent = !!(urgency && urgency.urgency_level && urgency.urgency_level !== 'none');
  const handoff = (step, reason, extra = {}) => ({ action: 'handoff', text: null, keyboard: null, step, reason, ...extra });
  if (kind === 'group') throw new Error('decide(): a group update has its own branch (SPEC-010 RH12)');
  if (kind === 'text') {
    // SPEC-010 RH4, RH5: the text a handoff waits for goes to reception (an urgency is answered first).
    if (inForce && handoffAwaiting) return handoff('text', null, { urgent });
    // SPEC-010 RH13–RH15: a complaint phrase opens the /queja confirmation; an urgency always wins.
    if (!urgent && detectComplaintPhrase(question)) {
      if (inForce) return handoff('ask', 'q');
      return reply(COMPLAINT_NO_CONSENT_TEXT, 'none');
    }
    if (inForce) return { action: 'core', text: null, keyboard: null };
    if (urgent) return reply(urgency.text, 'handoff');
    return lookupFailed ? reply(ERROR_TEXT, 'handoff') : notice;
  }
  // SPEC-010 RH1, RH3, RH6, RH7: the handoff steps; «No» needs nothing.
  if (kind === 'handoff_cancel') return handoff('cancel', null);
  if (kind === 'handoff' || kind === 'handoff_confirm') {
    return inForce ? handoff(kind === 'handoff' ? 'ask' : 'confirm', route.reason) : reply(HANDOFF_NO_CONSENT_TEXT, 'none');
  }
  if (lookupFailed) return reply(ERROR_TEXT, 'handoff');

  const withStatus = (status, keyboard) => reply(`${CONSENT_NOTICE}\n\n${status}`, keyboard);
  switch (kind) {
    case 'other':
      return inForce ? reply(TEXT_ONLY_TEXT, 'none') : notice;
    case 'start':
    case 'privacidad':
      if (inForce) return withStatus(STATUS_ACCEPTED.replace('{fecha}', formatDate(consent.decided_at)), 'withdraw');
      return kind === 'start' ? notice : withStatus(STATUS_NONE, 'consent');
    case 'accept':
      return route.version === CONSENT_TEXT_VERSION ? { action: 'accept', text: ACCEPTED_TEXT, keyboard: 'none' } : notice;
    case 'reject':
      return route.version === CONSENT_TEXT_VERSION ? reply(REJECTED_TEXT, 'none') : notice;
    case 'withdraw':
      return { action: 'withdraw', text: REVOKED_TEXT, keyboard: 'none' };
    case 'booking_command': // SPEC-007 BK8: every booking step needs consent in force
    case 'booking_button':
      if (inForce) return { action: 'booking', text: null, keyboard: null, consent: true };
      // SPEC-008 MC10: without consent, only «Anular» (bk:a), «Sí, anular» (bk:ac) and the «Mantener
      // mi cita» of the cancel confirmation (bk:v with a start) go through, flagged consent: false.
      if (kind === 'booking_button' && CANCEL_WITHOUT_CONSENT.test(route.data || '')) {
        return { action: 'booking', text: null, keyboard: null, consent: false };
      }
      return notice;
    case 'complaint_command': // SPEC-010 RH13, RH15
      return inForce ? handoff('ask', 'q') : reply(COMPLAINT_NO_CONSENT_TEXT, 'none');
    case 'rating': // SPEC-010 RH17, RH18
      return inForce ? { action: 'rating', text: null, keyboard: null, value: route.value } : notice;
    case 'unknown_button':
      return notice;
    default:
      throw new Error(`decide(): unknown route kind "${kind}"`);
  }
}

// --- n8n wiring ("Clasificar", SPEC-006 C23): keep the update as it is and add the route ---
return { json: { ...$json, route: classifyUpdate($json) } };

// SPEC-003 urgency detector (specs/004-urgencies/plan.md). Deterministic: no LLM, no network.
// Paste-ready for the n8n Code node "Detectar urgencia": no require/module/export here; the node
// appends only its input/output wiring (U16). Tested by n8n/code/urgencias.test.js.

// --- Configuration (U13) — the clinic's urgency phone. Example value until DEP-01. ---
const URGENCY_PHONE = '000 000 000';
const URGENCY_PHONE_IS_EXAMPLE = true;

// --- Fixed texts (spec "Fixed texts"; approved by the human 2026-11-19; pending clinical review) ---
const URGENT_MESSAGE =
  `No puedo valorar síntomas por aquí. Llama a la clínica al ${URGENCY_PHONE}. ` +
  'Si es grave o tienes dificultad para respirar, llama al 112.';
const SEVERE_MESSAGE =
  'Si tienes dificultad para respirar o tragar, una hemorragia que no para o te has dado un golpe ' +
  'fuerte en la cara o la cabeza, llama ahora al 112. No puedo valorar síntomas por aquí. ' +
  `Si no es una emergencia, llama a la clínica al ${URGENCY_PHONE}.`;
const EXAMPLE_PHONE_NOTICE =
  '(Este teléfono es de ejemplo: todavía no tenemos el número real de la clínica.)';

// --- Question flag and normalization (U10) ---
// The flag is read on the raw (pseudonymized) text, before normalize() removes punctuation.
function isQuestion(text) {
  return /[¿?]/.test(String(text ?? ''));
}

// Lowercase, no accents, SPEC-001 placeholders removed, punctuation removed, single spaces.
function normalize(text) {
  return String(text ?? '')
    .toLowerCase()
    .normalize('NFD').replace(/\p{M}+/gu, '')
    .replace(/\[(nombre|telefono|dni|email)\]/g, ' ')
    .replace(/[^\p{L}\p{N}\s]+/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// --- Rule tables (provisional clinical criteria, clarifications A1/A3; pending Prince Calderon).
// Every pattern works on normalize()d text. A rule with several patterns needs all of them. ---
const SWELLING = /\b(hinch\w*|inflam\w*)\b/;
const BLEEDING = /\bsangr\w*/;
const BLOW = /\b(golpe\w*|caida|me cai|me he caido|se ha caido|accidente|traumatismo)\b/;

// Removed from the text before classifying (U8).
const FIGURATIVE = [
  { id: 'fig_duele_que', re: /\b(?:me |te |nos )?duele (?:pensar|pagar|gastar|tener que|que|ver|saber|el bolsillo|la cartera)\b/g },
  { id: 'fig_de_golpe', re: /\bde golpe\b/g },
  { id: 'fig_me_muero_de', re: /\bme muero de (?:ganas|risa)\b/g },
];

// A1 — severe signs.
const SEVERE_RULES = [
  { id: 'sev_breath_swallow', all: [/\b(?:no puedo|me cuesta|le cuesta|dificultad para|no consigo|no puede)(?: \w+)? (?:respirar|tragar)\b/] },
  { id: 'sev_swelling_neck_eye', all: [SWELLING, /\b(?:cuello|ojo|ojos|no puedo abrir)\b/] },
  { id: 'sev_bleeding_nonstop', all: [BLEEDING, /\b(?:no para|no se para|no deja de|sin parar|no se corta|a chorro)\b/] },
  { id: 'sev_blow_face_head', all: [BLOW, /\b(?:cara|cabeza|mandibula)\b/] },
  { id: 'sev_blow_unconscious', all: [BLOW, /\b(?:desmay\w*|conocimiento|inconsciente)\b/] },
  { id: 'sev_blow_tooth_out', all: [BLOW, /\b(?:se me ha caido|se le ha caido|arrancado)(?: \w+)? (?:un |el )?(?:diente|muela)\b/] },
  { id: 'sev_fever_swelling', all: [/\bfiebre\b/, SWELLING] },
];

// A3 — symptom terms.
const SYMPTOM_TERMS = [
  { id: 'sym_pain', all: [/\b(?:dolor\w*|duele|duelen|doler|dolera|doloros\w*|molest\w*|pinchazo\w*)\b/] },
  { id: 'sym_bleeding', all: [BLEEDING] },
  { id: 'sym_swelling', all: [SWELLING] },
  { id: 'sym_fever', all: [/\bfiebre\b/] },
  { id: 'sym_infection', all: [/\b(?:pus|absces\w*|flemon\w*|infecc\w*)\b/] },
  { id: 'sym_blow', all: [/\b(?:golpe\w*|traumatismo)\b/] },
  { id: 'sym_tooth_damage', all: [
    /\b(?:diente|dientes|muela|muelas|corona|empaste|funda|puente)\b/,
    /\b(?:roto|rota|partido|partida|caido|caida|se mueve|se me mueve|suelto|suelta|flojo|floja|movido)\b/,
  ] },
];

// Hypothetical forms about a treatment: they take precedence over "me" (plan, step 4).
const HYPOTHETICAL = [
  /\b(?:me |te )?(?:va|van) a doler\b/g,
  /\bdolera\b/g,
  /\bes doloros[oa]\b/g,
  /\bduele mucho (?:la|el)\b/g,
];

// Signs that the patient reports an own, current or recent state.
const PERSONAL_MARKERS = [
  /\bme (?:duele\w*|sangr\w*|molest\w*|hinch\w*|ha|he|han|esta\w*|noto|sale|cuesta|di|hicieron|pusieron)\b/,
  /\bmis?\b/,
  /\b(?:tengo|tiene|estoy|llevo|lleva|noto|sigue)\b/,
  /\bse (?:me|le)\b/,
  /\bdesde (?:ayer|hace|esta|el|que)\b/,
  /\b(?:hoy|anoche|ahora)\b/,
];

const TREATMENT_WORDS =
  /\b(?:limpieza|blanqueamiento|ortodoncia|implantes?|endodoncia|extraccion|empastes?|tratamiento|anestesia|revision|radiografia|brackets)\b/;

function firing(rules, text) {
  return rules.filter((r) => r.all.every((re) => re.test(text))).map((r) => r.id);
}

// --- Classification (U5–U9) ---
function detectUrgency(text) {
  const question = isQuestion(text);
  let t = normalize(text);
  const matched = [];

  for (const f of FIGURATIVE) {
    if (f.re.test(t)) {
      matched.push(f.id);
      f.re.lastIndex = 0;
      t = t.replace(f.re, ' ').replace(/\s+/g, ' ').trim();
    }
    f.re.lastIndex = 0;
  }

  const severe = firing(SEVERE_RULES, t);
  if (severe.length) return { level: 'severe', matched: matched.concat(severe), question };

  const symptoms = firing(SYMPTOM_TERMS, t);
  if (!symptoms.length) return { level: 'none', matched, question };
  matched.push(...symptoms);

  let withoutHypothetical = t;
  let hypothetical = false;
  for (const re of HYPOTHETICAL) {
    re.lastIndex = 0;
    if (re.test(withoutHypothetical)) {
      hypothetical = true;
      re.lastIndex = 0;
      withoutHypothetical = withoutHypothetical.replace(re, ' ');
    }
    re.lastIndex = 0;
  }
  const personal = PERSONAL_MARKERS.some((re) => re.test(withoutHypothetical));
  if (!personal && TREATMENT_WORDS.test(t) && (question || hypothetical)) {
    matched.push(hypothetical ? 'info_hypothetical' : 'info_question');
    return { level: 'none', matched, question };
  }

  matched.push(personal ? 'reported_state' : 'doubt');
  return { level: 'urgent', matched, question };
}

// --- Reply (U11–U13): fixed text only, built from the level, never from the message. ---
function composeUrgencyReply(level) {
  const base = level === 'severe' ? SEVERE_MESSAGE : URGENT_MESSAGE;
  return URGENCY_PHONE_IS_EXAMPLE ? `${base}\n\n${EXAMPLE_PHONE_NOTICE}` : base;
}

// --- n8n wiring (U16; SPEC-005: no chat id in the core workflow) ---
const r = detectUrgency($json.question);
if (r.level === 'none') return { json: { question: $json.question, urgency_level: 'none' } };
return { json: {
  text: composeUrgencyReply(r.level), handoff: true,
  reason: 'urgency', urgency_level: r.level, matched: r.matched,
} };

// SPEC-006 consent module (specs/006-consent/spec.md, plan.md Step 1).
// Paste-ready: the n8n Code nodes "Clasificar" and "Decidir" of lifecenter-telegram-demo carry this
// exact code followed only by their input/output wiring (C23). No require, no network, no state.

// --- Configuration (C22). Change the version whenever CONSENT_NOTICE changes: everyone is asked again.
const CONSENT_TEXT_VERSION = '1';

// --- Fixed texts (spec "Fixed texts", approved by the human 2026-11-21) ---
const CONSENT_NOTICE =
  'Hola, soy el asistente de LifeCenter. Para responderte: quito tu nombre, teléfono, DNI y email ' +
  'de los mensajes antes de procesarlos; envío la consulta a un modelo de IA externo (Gemini, de ' +
  'Google), y guardo el recorrido de cada consulta, sin tus datos, durante 30 días. Si me cuentas un ' +
  'síntoma te daré siempre el teléfono de la clínica. Esto es una demostración: no escribas datos ' +
  'reales. ¿Aceptas?';
const ACCEPTED_TEXT = 'Gracias. Ya puedes escribirme tu consulta.';
const REJECTED_TEXT =
  'De acuerdo, no procesaré tus consultas. Puedes llamar a recepción. Si cambias de opinión, escribe /privacidad.';
const REVOKED_TEXT =
  'He retirado tu consentimiento. No procesaré más consultas tuyas. Si cambias de opinión, escribe /privacidad.';
const STATUS_ACCEPTED = 'Estado: aceptaste este aviso el {fecha}.';
const STATUS_NONE = 'Estado: no has aceptado este aviso.';
// Copies of CHG-001 texts this module now composes: D7 (error) and D12 (no text).
const ERROR_TEXT = 'Ahora mismo no puedo responder. ¿Quieres que pase tu consulta a recepción?';
const TEXT_ONLY_TEXT = 'Solo puedo leer mensajes de texto. ¿Me escribes tu consulta?';
// SPEC-010 (spec "Fixed texts", verified 2026-11-24): the D8 text, now chosen here, for a handoff without
// consent; and the reply to a complaint without consent.
const HANDOFF_NO_CONSENT_TEXT = 'Ahora mismo no puedo pasar tu consulta automáticamente. Llama a recepción en horario de atención.';
const COMPLAINT_NO_CONSENT_TEXT =
  'Para pasar tu queja a recepción necesito tu consentimiento (/privacidad). También puedes llamar a recepción en horario de atención.';

// --- Buttons (C7): labels and callback_data, each at most 64 bytes ---
const BUTTON_LABELS = {
  handoff: 'Hablar con recepción',
  accept: 'Acepto',
  reject: 'No acepto',
  withdraw: 'Retirar consentimiento',
};
const CALLBACK_HANDOFF = 'handoff';
const CALLBACK_WITHDRAW = 'consent:withdraw';
const callbackAccept = (version = CONSENT_TEXT_VERSION) => `consent:accept:${version}`;
const callbackReject = (version = CONSENT_TEXT_VERSION) => `consent:reject:${version}`;

// --- Commands (spec "Command"): exactly /start or /privacidad, optionally @<bot>, spaces ignored,
// in any letter case (phone keyboards capitalize the first letter) ---
// SPEC-007: /cita and /micita are booking commands (any letter case, like the others).
// SPEC-010: /queja opens the complaint path (RH13).
const COMMAND = /^\s*\/(start|privacidad|cita|micita|queja)(?:@[A-Za-z0-9_]+)?\s*$/i;
const BOOKING_COMMANDS = ['cita', 'micita'];
function parseCommand(text) {
  const m = COMMAND.exec(typeof text === 'string' ? text : '');
  return m ? m[1].toLowerCase() : null;
}

// --- Buttons: callback_data → { kind, version } ---
const CONSENT_CALLBACK = /^consent:(accept|reject):(.+)$/;
// SPEC-010 RH2, RH3, RH6, RH17: handoff:<reason> (the old `handoff` is a request), «Sí, pasar a
// recepción» (hs:<reason>), «No» (hn), and the ratings (rt:u / rt:d). «Cerrar» (hc:) only exists in groups.
const HANDOFF_CALLBACK = /^(handoff|hs):([aupq])$/;
const RATING_CALLBACK = /^rt:([ud])$/;
function parseCallback(data) {
  if (data === CALLBACK_HANDOFF) return { kind: 'handoff', version: null, reason: 'p' };
  const h = HANDOFF_CALLBACK.exec(typeof data === 'string' ? data : '');
  if (h) return { kind: h[1] === 'hs' ? 'handoff_confirm' : 'handoff', version: null, reason: h[2] };
  if (data === 'hn') return { kind: 'handoff_cancel', version: null };
  const rt = RATING_CALLBACK.exec(typeof data === 'string' ? data : '');
  if (rt) return { kind: 'rating', version: null, value: rt[1] === 'u' ? 'up' : 'down' };
  if (data === CALLBACK_WITHDRAW) return { kind: 'withdraw', version: null };
  if (typeof data === 'string' && data.startsWith('bk:')) return { kind: 'booking_button', version: null }; // SPEC-007
  const m = CONSENT_CALLBACK.exec(typeof data === 'string' ? data : '');
  return m ? { kind: m[1], version: m[2] } : { kind: 'unknown_button', version: null };
}

// --- A Telegram update → route. fromId is a string: it is only ever passed to Neon as $1 (C18). ---
function classifyUpdate(update) {
  const asId = (v) => (v === undefined || v === null ? null : String(v));
  const cq = update && update.callback_query;
  // SPEC-010 RH12, A3: anything from a chat that is not private is a group update. It never carries the
  // sender's id, and never reaches the consent logic.
  const chatOf = cq ? cq.message && cq.message.chat : update && update.message && update.message.chat;
  if (chatOf && chatOf.type && chatOf.type !== 'private') {
    const gm = cq ? cq.message : update.message;
    const reply = !cq && gm.reply_to_message;
    return {
      kind: 'group',
      chatId: asId(chatOf.id),
      messageId: gm && gm.message_id !== undefined ? gm.message_id : null,
      replyToMessageId: reply ? reply.message_id : null,
      replyToBot: !!(reply && reply.from && reply.from.is_bot),
      text: !cq && typeof gm.text === 'string' ? gm.text : null,
      callbackData: cq ? cq.data : null,
      callbackQueryId: cq && cq.id !== undefined ? cq.id : null,
    };
  }
  if (cq) {
    const parsed = parseCallback(cq.data);
    const route = {
      kind: parsed.kind,
      fromId: asId(cq.from && cq.from.id),
      chatId: cq.message && cq.message.chat ? cq.message.chat.id : null,
      callbackQueryId: cq.id === undefined ? null : cq.id,
      version: parsed.version,
    };
    if (parsed.kind === 'booking_button') return { ...route, data: cq.data }; // SPEC-007
    if ('reason' in parsed) return { ...route, reason: parsed.reason }; // SPEC-010
    if ('value' in parsed) return { ...route, value: parsed.value };
    return route;
  }
  const m = (update && update.message) || {};
  const hasText = typeof m.text === 'string' && m.text !== '';
  const command = hasText ? parseCommand(m.text) : null;
  const booking = BOOKING_COMMANDS.includes(command);
  const complaint = command === 'queja'; // SPEC-010 RH13
  const route = {
    kind: booking ? 'booking_command' : complaint ? 'complaint_command' : command || (hasText ? 'text' : 'other'),
    fromId: asId(m.from && m.from.id),
    chatId: m.chat ? m.chat.id : null,
    callbackQueryId: null,
    version: null,
  };
  return booking || complaint ? { ...route, data: command } : route; // SPEC-007: /cita, /micita; SPEC-010: /queja
}

// --- SPEC-010 RH13, RH14: complaint phrases, a strict list (evals/complaint_phrases.yaml) ---
// Works on the pseudonymized text. A match only opens the /queja confirmation; it never posts anything.
function normalizeComplaintText(text) {
  return String(text ?? '')
    .toLowerCase()
    .normalize('NFD').replace(/\p{M}+/gu, '')
    .replace(/\[(nombre|telefono|dni|email)\]/g, ' ')
    .replace(/[^\p{L}\p{N}\s]+/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
const COMPLAINT_WORDS = /\b(?:queja|quejas|quejar|quejarme|reclamacion|reclamaciones|reclamar)\b/;
// Not a complaint: no complaint, someone else complaining, or an insurance claim.
const COMPLAINT_BLOCKERS = [
  /\b(?:no tengo|sin) (?:ninguna )?quejas?\b/,
  /\bno me quejo\b/,
  /\bse (?:queja|quejan|quejaba|quejo)\b/,
  /\b(?:seguro|aseguradora|reembolso|mutua|tramit\w*)\b/,
];
function detectComplaintPhrase(text) {
  const t = normalizeComplaintText(text);
  return COMPLAINT_WORDS.test(t) && !COMPLAINT_BLOCKERS.some((re) => re.test(t));
}

// --- SPEC-008 MC10: the only booking buttons allowed without consent (one start code each) ---
const CANCEL_WITHOUT_CONSENT = /^bk:(?:a|ac|v):[0-9a-z]{1,8}$/;

// --- Consent in force (C22): accepted with the current version; anything else is no consent ---
function isConsentInForce(row) {
  return !!row && row.status === 'accepted' && row.text_version === CONSENT_TEXT_VERSION;
}

// --- dd/mm/aaaa in Europe/Madrid ---
function formatDate(decidedAt) {
  const parts = new Intl.DateTimeFormat('es-ES', {
    timeZone: 'Europe/Madrid', day: '2-digit', month: '2-digit', year: 'numeric',
  }).formatToParts(new Date(decidedAt));
  const get = (type) => parts.find((p) => p.type === type).value;
  return `${get('day')}/${get('month')}/${get('year')}`;
}

// --- What to do with an update (plan Step 1, decision table; C2–C16) ---
// urgency: the output of "Detectar urgencia" (B's wiring), or null if it did not run.
// consent: the row from consent_get ({} when there is none); lookupFailed: the lookup errored.
// SPEC-010: question is the pseudonymized text (for the complaint phrases); handoffAwaiting says whether a
// handoff of this patient waits for the text for reception (from the consent lookup).
function decide({ route, urgency, consent, lookupFailed, question = null, handoffAwaiting = false }) {
  const reply = (text, keyboard) => ({ action: 'reply', text, keyboard });
  const notice = reply(CONSENT_NOTICE, 'consent');
  const inForce = !lookupFailed && isConsentInForce(consent);
  const kind = route && route.kind;

  const urgent = !!(urgency && urgency.urgency_level && urgency.urgency_level !== 'none');
  const handoff = (step, reason, extra = {}) => ({ action: 'handoff', text: null, keyboard: null, step, reason, ...extra });
  if (kind === 'group') throw new Error('decide(): a group update has its own branch (SPEC-010 RH12)');
  if (kind === 'text') {
    // SPEC-010 RH4, RH5: the text a handoff waits for goes to reception (an urgency is answered first).
    if (inForce && handoffAwaiting) return handoff('text', null, { urgent });
    // SPEC-010 RH13–RH15: a complaint phrase opens the /queja confirmation; an urgency always wins.
    if (!urgent && detectComplaintPhrase(question)) {
      if (inForce) return handoff('ask', 'q');
      return reply(COMPLAINT_NO_CONSENT_TEXT, 'none');
    }
    if (inForce) return { action: 'core', text: null, keyboard: null };
    if (urgent) return reply(urgency.text, 'handoff');
    return lookupFailed ? reply(ERROR_TEXT, 'handoff') : notice;
  }
  // SPEC-010 RH1, RH3, RH6, RH7: the handoff steps; «No» needs nothing.
  if (kind === 'handoff_cancel') return handoff('cancel', null);
  if (kind === 'handoff' || kind === 'handoff_confirm') {
    return inForce ? handoff(kind === 'handoff' ? 'ask' : 'confirm', route.reason) : reply(HANDOFF_NO_CONSENT_TEXT, 'none');
  }
  if (lookupFailed) return reply(ERROR_TEXT, 'handoff');

  const withStatus = (status, keyboard) => reply(`${CONSENT_NOTICE}\n\n${status}`, keyboard);
  switch (kind) {
    case 'other':
      return inForce ? reply(TEXT_ONLY_TEXT, 'none') : notice;
    case 'start':
    case 'privacidad':
      if (inForce) return withStatus(STATUS_ACCEPTED.replace('{fecha}', formatDate(consent.decided_at)), 'withdraw');
      return kind === 'start' ? notice : withStatus(STATUS_NONE, 'consent');
    case 'accept':
      return route.version === CONSENT_TEXT_VERSION ? { action: 'accept', text: ACCEPTED_TEXT, keyboard: 'none' } : notice;
    case 'reject':
      return route.version === CONSENT_TEXT_VERSION ? reply(REJECTED_TEXT, 'none') : notice;
    case 'withdraw':
      return { action: 'withdraw', text: REVOKED_TEXT, keyboard: 'none' };
    case 'booking_command': // SPEC-007 BK8: every booking step needs consent in force
    case 'booking_button':
      if (inForce) return { action: 'booking', text: null, keyboard: null, consent: true };
      // SPEC-008 MC10: without consent, only «Anular» (bk:a), «Sí, anular» (bk:ac) and the «Mantener
      // mi cita» of the cancel confirmation (bk:v with a start) go through, flagged consent: false.
      if (kind === 'booking_button' && CANCEL_WITHOUT_CONSENT.test(route.data || '')) {
        return { action: 'booking', text: null, keyboard: null, consent: false };
      }
      return notice;
    case 'complaint_command': // SPEC-010 RH13, RH15
      return inForce ? handoff('ask', 'q') : reply(COMPLAINT_NO_CONSENT_TEXT, 'none');
    case 'rating': // SPEC-010 RH17, RH18
      return inForce ? { action: 'rating', text: null, keyboard: null, value: route.value } : notice;
    case 'unknown_button':
      return notice;
    default:
      throw new Error(`decide(): unknown route kind "${kind}"`);
  }
}

// --- n8n wiring ("Decidir", SPEC-006 C23, SPEC-010) ---
const route = $('Clasificar').item.json.route;
const urgency = $('Detectar urgencia').isExecuted ? $('Detectar urgencia').item.json : null;
const question = $('Seudonimizar').isExecuted ? $('Seudonimizar').item.json.question : null; // SPEC-010: complaint phrases
const lookupFailed = !!$json.error; // error output of "Consultar consentimiento" (C6)
const handoffAwaiting = !lookupFailed && $json.handoff_awaiting === true; // SPEC-010 RH4
const d = decide({ route, urgency, consent: lookupFailed ? null : $json, lookupFailed, question, handoffAwaiting });
return { json: {
  ...d, chatId: route.chatId,
  callbackAccept: callbackAccept(), callbackReject: callbackReject(),
  onWriteError: { action: 'reply', text: ERROR_TEXT, keyboard: 'handoff' },
} };

// SPEC-006 C8, C10: after "Guardar aceptación" or "Guardar retirada". If the write failed (error
// output), reply with D7 and the handoff button prepared by "Decidir"; otherwise send its decision.
const d = $('Decidir').item.json;
return { json: !!$json.error ? { ...d, ...d.onWriteError } : d };

