const CHANGE_STEPS = { v: 'keep', a: 'cancel_ask', ac: 'cancel', x: 'move', xm: 'move_more', xs: 'move_slot', xc: 'move_confirm',
  ry: 'reminder_on', rn: 'reminder_off', rq: 'reminder_clear', i: 'attend' };
